mod commands;
mod db;
mod error;
mod file_center;
mod hash;
mod limits;

use error::{AppError, AppResult};
use serde::Serialize;
use sha2::{Digest, Sha256};
use std::{fs::{self, File}, io::{Read, Seek, SeekFrom}, path::{Component, Path, PathBuf}};
use tauri::Manager;
use uuid::Uuid;

#[derive(Debug, Serialize)] struct AppHealth { ok: bool, version: &'static str }
#[derive(Debug, Serialize)] struct ProjectInfo { id: String, path: String }
#[derive(Debug, Serialize)] struct TokenEstimate { method: &'static str, count: usize, approximate: bool, provider: Option<String>, model: Option<String>, limitation: Option<String> }

fn safe_project_id(id:&str)->AppResult<()> { if id.is_empty()||id.len()>64||!id.chars().all(|c|c.is_ascii_alphanumeric()||c=='-'||c=='_'){return Err(AppError::new("INVALID_REQUEST","project_id inválido."));} Ok(()) }
fn safe_logical_path(path:&str)->AppResult<PathBuf>{if path.is_empty()||path.len()>512{return Err(AppError::new("INVALID_FILE","Caminho lógico inválido."));} let p=Path::new(path); let mut out=PathBuf::new(); let mut depth=0usize; for c in p.components(){match c{Component::Normal(v)=>{out.push(v);depth+=1;} Component::CurDir=>{} Component::ParentDir|Component::RootDir|Component::Prefix(_)=>return Err(AppError::new("PATH_NOT_ALLOWED","Caminho lógico fora do projeto.")),}} if depth==0||depth>limits::MAX_PATH_DEPTH{return Err(AppError::new("PATH_NOT_ALLOWED","Profundidade de caminho não permitida."));} Ok(out)}
fn project_root(app:&tauri::AppHandle,project_id:&str)->AppResult<PathBuf>{safe_project_id(project_id)?; app.path().app_data_dir().map(|p|p.join("storage").join("projects").join(project_id)).map_err(|_|AppError::new("STORAGE_ERROR","Não foi possível localizar o armazenamento."))}
fn timestamp()->String{format!("{}",std::time::SystemTime::now().duration_since(std::time::UNIX_EPOCH).unwrap_or_default().as_secs())}
fn ensure_blob(root:&Path,sha:&str,bytes:&[u8])->AppResult<String>{let blob_rel=format!("blobs/{}",sha);let blob_abs=root.join(&blob_rel); if blob_abs.exists(){let meta=fs::metadata(&blob_abs).map_err(|_|AppError::new("STORAGE_ERROR","Não foi possível verificar o blob."))?;if !meta.is_file()||meta.len()!=bytes.len() as u64{return Err(AppError::new("STORAGE_ERROR","Blob existente está inconsistente."));}let mut f=File::open(&blob_abs).map_err(|_|AppError::new("STORAGE_ERROR","Não foi possível verificar o blob."))?;let mut data=Vec::with_capacity(bytes.len());f.read_to_end(&mut data).map_err(|_|AppError::new("STORAGE_ERROR","Não foi possível verificar o blob."))?;if hash::sha256_bytes(&data)!=sha{return Err(AppError::new("STORAGE_ERROR","Blob existente está corrompido."));}return Ok(blob_rel)} let tmp=root.join(format!(".blob-{}.tmp",Uuid::new_v4()));fs::write(&tmp,bytes).map_err(|_|AppError::new("STORAGE_ERROR","Não foi possível gravar o blob temporário."))?;match fs::rename(&tmp,&blob_abs){Ok(())=>Ok(blob_rel),Err(_)=>{let _=fs::remove_file(&tmp);if blob_abs.exists(){let mut f=File::open(&blob_abs).map_err(|_|AppError::new("STORAGE_ERROR","Não foi possível verificar o blob."))?;let mut data=Vec::new();f.read_to_end(&mut data).map_err(|_|AppError::new("STORAGE_ERROR","Não foi possível verificar o blob."))?;if data.len()!=bytes.len()||hash::sha256_bytes(&data)!=sha{return Err(AppError::new("STORAGE_ERROR","Blob existente está corrompido."));}Ok(blob_rel)}else{Err(AppError::new("STORAGE_ERROR","Não foi possível finalizar o armazenamento do blob."))}}}}
fn allowed_extension(path:&str)->bool{matches!(Path::new(path).extension().and_then(|e|e.to_str()).map(|s|s.to_ascii_lowercase()).as_deref(),Some("txt")|Some("md")|Some("json")|Some("html")|Some("css"))}
fn read_source_safely(source:&Path)->AppResult<Vec<u8>>{let mut f=File::open(source).map_err(|_|AppError::new("FILE_NOT_FOUND","Arquivo não encontrado."))?;let meta=f.metadata().map_err(|_|AppError::new("INVALID_FILE","Não foi possível verificar o arquivo."))?;if !meta.is_file(){return Err(AppError::new("INVALID_FILE","O caminho informado não é um arquivo regular."));}let mut bytes=Vec::new();f.take(limits::MAX_FILE_BYTES+1).read_to_end(&mut bytes).map_err(|_|AppError::new("INVALID_FILE","Não foi possível ler o arquivo informado."))?;if bytes.len() as u64>limits::MAX_FILE_BYTES{return Err(AppError::with_details("FILE_TOO_LARGE","O arquivo excede o limite permitido.",serde_json::json!({"limit_bytes":limits::MAX_FILE_BYTES,"actual_bytes":bytes.len()})));}if std::str::from_utf8(&bytes).is_err(){return Err(AppError::new("ENCODING_INVALID","O arquivo não é UTF-8 válido."));}Ok(bytes)}
#[tauri::command] fn health()->AppResult<AppHealth>{Ok(AppHealth{ok:true,version:"0.1.0"})}
#[tauri::command] fn sha256_text(input:String)->AppResult<String>{let mut h=Sha256::new();h.update(input.as_bytes());Ok(format!("{:x}",h.finalize()))}
#[tauri::command] fn estimate_tokens(input:String)->AppResult<TokenEstimate>{let count=((input.chars().count() as f64)/4.0).ceil() as usize;Ok(TokenEstimate{method:"local_estimate",count,approximate:true,provider:None,model:None,limitation:Some("Estimativa local por caracteres; não substitui a contagem do provedor.".into())})}
#[tauri::command] fn initialize_project(app:tauri::AppHandle,project_id:String)->AppResult<ProjectInfo>{let root=project_root(&app,&project_id)?;fs::create_dir_all(root.join("blobs")).map_err(|_|AppError::new("STORAGE_ERROR","Não foi possível gravar no armazenamento."))?;let db_path=root.join("db.sqlite");db::open(&db_path)?;Ok(ProjectInfo{id:project_id,path:root.to_string_lossy().into_owned()})}
#[tauri::command] fn import_text_file(app:tauri::AppHandle,project_id:String,logical_path:String,source_path:String)->AppResult<String>{let logical=safe_logical_path(&logical_path)?;if !allowed_extension(&logical_path){return Err(AppError::new("FILE_TYPE_NOT_SUPPORTED","Tipo de arquivo não suportado pela Foundation."));}let source=PathBuf::from(source_path);let bytes=read_source_safely(&source)?;let root=project_root(&app,&project_id)?;fs::create_dir_all(root.join("blobs")).map_err(|_|AppError::new("STORAGE_ERROR","Não foi possível acessar o armazenamento."))?;let conn=db::open(&root.join("db.sqlite"))?;let sha=hash::sha256_bytes(&bytes);let blob_rel=ensure_blob(&root,&sha,&bytes)?;let now=timestamp();let tx=conn.unchecked_transaction().map_err(|_|AppError::new("DATABASE_ERROR","Não foi possível iniciar a transação."))?;tx.execute("INSERT OR IGNORE INTO projects(id,name,created_at) VALUES(?1,?2,?3)",rusqlite::params![project_id,project_id,now]).map_err(|_|AppError::new("DATABASE_ERROR","Não foi possível registrar o projeto."))?;tx.execute("INSERT OR IGNORE INTO blobs(sha256,byte_len,relative_path,created_at) VALUES(?1,?2,?3,?4)",rusqlite::params![sha,bytes.len() as i64,blob_rel,now]).map_err(|_|AppError::new("DATABASE_ERROR","Não foi possível registrar o blob."))?;let file_id=Uuid::new_v4().to_string();tx.execute("INSERT OR IGNORE INTO files(id,project_id,logical_path,created_at) VALUES(?1,?2,?3,?4)",rusqlite::params![file_id,project_id,logical.to_string_lossy(),now]).map_err(|_|AppError::new("DATABASE_ERROR","Não foi possível registrar o arquivo."))?;let actual_file_id:String=tx.query_row("SELECT id FROM files WHERE project_id=?1 AND logical_path=?2",rusqlite::params![project_id,logical.to_string_lossy()],|r|r.get(0)).map_err(|_|AppError::new("DATABASE_ERROR","Não foi possível localizar o arquivo registrado."))?;let last:i64=tx.query_row("SELECT COALESCE(MAX(version_no),0) FROM file_versions WHERE file_id=?1",rusqlite::params![actual_file_id],|r|r.get(0)).map_err(|_|AppError::new("DATABASE_ERROR","Não foi possível consultar as versões do arquivo."))?;if last>0{let same:Option<String>=tx.query_row("SELECT blob_sha256 FROM file_versions WHERE file_id=?1 AND version_no=?2",rusqlite::params![actual_file_id,last],|r|r.get(0)).map_err(|_|AppError::new("DATABASE_ERROR","Não foi possível verificar a versão atual."))?;if same.as_deref()==Some(sha.as_str()){tx.commit().map_err(|_|AppError::new("DATABASE_ERROR","Não foi possível confirmar a importação."))?;return Ok(sha)}}let next=last+1;tx.execute("INSERT INTO file_versions(id,file_id,version_no,blob_sha256,byte_len,created_at) VALUES(?1,?2,?3,?4,?5,?6)",rusqlite::params![Uuid::new_v4().to_string(),actual_file_id,next,sha,bytes.len() as i64,now]).map_err(|_|AppError::new("DATABASE_ERROR","Não foi possível registrar a nova versão."))?;tx.commit().map_err(|_|AppError::new("DATABASE_ERROR","Não foi possível confirmar a importação."))?;Ok(sha)}
#[cfg(test)] mod tests;
#[cfg_attr(mobile,tauri::mobile_entry_point)] pub fn run(){tauri::Builder::default().invoke_handler(tauri::generate_handler![health,sha256_text,estimate_tokens,initialize_project,import_text_file,file_center::list_project_files,file_center::read_file_version]).setup(|app|{let _=app.path();Ok(())}).run(tauri::generate_context!()).expect("error while running TokenSaver AI");}
